mapper.select:
SELECT l.id, l.user_id AS userId, u.user_name AS userName, l.type, l.amount, l.balance_after AS balanceAfter, l.order_no AS orderNo, l.remark, DATE_FORMAT(l.create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM u_account_log l LEFT JOIN user u ON l.user_id = u.id
AND l.user_id = #{userId}
AND l.type = #{type}
AND l.create_time >= CONCAT(#{startDate}, ' 00:00:00')
AND l.create_time <= CONCAT(#{endDate}, ' 23:59:59')
ORDER BY l.create_time DESC
